export interface Intent { goal: string; plan: string }

export function parseIntent(body: string): Intent | null {
  const m = body.match(/<!-- review-intent v1 -->([\s\S]*?)<!-- \/review-intent -->/);
  if (!m) return null;
  return { goal: field(m[1], 'Goal'), plan: field(m[1], 'Plan') };
}

function field(block: string, label: string): string {
  const m = block.match(new RegExp('\\*\\*' + label + ':\\*\\* (.*)'));
  return m ? m[1].trim() : '';
}
